import type { FormEvent } from 'react'
import { ArrowLeft, ArrowRight, ArrowUpRight, Bookmark, BriefcaseBusiness, Check, CheckCircle2, ChevronDown, Compass, Copy, Download, FileText, Heart, Home, Info, LockKeyhole, LogOut, MapPin, Menu, MessageCircle, Plus, Search, Shield, ShieldCheck, Sparkles, Trash2, UserRound, X } from 'lucide-react'
import L from 'leaflet'
import { MapContainer, Marker, Popup, TileLayer } from 'react-leaflet'
import 'leaflet/dist/leaflet.css'
import type { Opportunity, OpportunityLoadStatus } from './data/types'
import { loadOpportunities } from './data/opportunitySource'
import { signInAdmin, signInJobSeeker, signUpJobSeeker, type AdminSession } from './data/adminAuth'
