type Page = 'home' | 'opportunities' | 'path' | 'goals' | 'coach' | 'profile' | 'cv' | 'auth' | 'admin'
type Profile = { name: string; location: string; education: string; about: string; skills: string[] }
type CV = { id:string; title:string; email:string; phone:string; summary:string; experience:string; education:string; template:'clean'|'warm' }
type Goal = { id:string; title:string; opportunityId?:string; done:boolean; createdAt:string }
type UserReport = { id:string; opportunityId:string; reason:string; note:string; createdAt:string }
type Store = { saved: string[]; completed: string[]; applied: string[]; answers: { question: string; answer: string; date: string }[]; profile: Profile; cvs:CV[]; goals:Goal[]; reports:UserReport[] }
type ConfirmationConfig = { title:string; message:string; confirmLabel:string; onConfirm:()=>void }
const STORE_KEY_PREFIX = 'thusapath-user-v2:'
const initialStore: Store = { saved: [], completed: [], applied: [], answers: [], profile: { name: '', location: '', education: '', about: '', skills: [] }, cvs:[{id:'cv-first',title:'My CV',email:'',phone:'',summary:'',experience:'',education:'',template:'clean'}], goals:[], reports:[] }
const questions = [
  { title: 'Tell me about yourself', group: 'About you', guide: 'Try present, past, future: what you are like now, something you have done, and what you hope to do next.' },
  { title: 'Why do you want this opportunity?', group: 'Motivation', guide: 'Say what interests you, what you would bring, and what you hope to learn.' },
  { title: 'What is something you are good at?', group: 'Your strengths', guide: 'Choose one strength and give a small example from school, home or your community.' },
  { title: 'Tell me about a time you helped someone', group: 'Your experience', guide: 'Try STAR: what was happening, what you needed to do, what you did, and how it turned out.' },
  { title: 'What would you do if a customer was upset?', group: 'A situation', guide: 'Explain how you would stay calm, listen, and find someone who can help if you need to.' },
  { title: 'What days and times can you work?', group: 'Practical details', guide: 'Be honest about your availability. Mention any travel limits that affect your schedule.' },
  { title: 'Do you have any questions for us?', group: 'Your questions', guide: 'You could ask what a normal day looks like or what training is provided.' },
]

function getStore(userId?: string): Store {
  if (!userId) return { ...initialStore, saved: [], completed: [], applied: [], answers: [], profile: { ...initialStore.profile, skills: [] }, cvs: initialStore.cvs.map(cv => ({ ...cv })), goals: [], reports: [] }
  try {
    const saved = localStorage.getItem(`${STORE_KEY_PREFIX}${encodeURIComponent(userId)}`)
    if (!saved) return initialStore
    const parsed = JSON.parse(saved)
    const migrated = { ...initialStore, ...parsed, cvs: Array.isArray(parsed.cvs) && parsed.cvs.length ? parsed.cvs : initialStore.cvs }
    // Earlier prototypes shipped with a made-up profile and sample opportunity IDs.
    if (migrated.profile?.name === 'Matome' && migrated.profile?.location === 'Polokwane, Limpopo') {
      migrated.profile = initialStore.profile
      migrated.saved = migrated.saved.filter((id: string) => !id.startsWith('opp-'))
      migrated.applied = migrated.applied.filter((id: string) => !id.startsWith('opp-'))
    }
    return migrated
  } catch { return initialStore }
}

function getSavedJobSeekerSession(): AdminSession | null {
  try {
    const value = sessionStorage.getItem('thusapath-auth-session')
    if (!value) return null
    const session = JSON.parse(value) as AdminSession
    if (!session.email || !session.accessToken || session.expiresAt <= Date.now()) {
      sessionStorage.removeItem('thusapath-auth-session')
      return null
    }
    return session
  } catch { return null }
}

function App() {
  const [jobSeekerSession, setJobSeekerSession] = useState<AdminSession | null>(getSavedJobSeekerSession)
  const [storeOwnerId, setStoreOwnerId] = useState<string | null>(() => jobSeekerSession?.userId ?? null)
  const [store, setStore] = useState<Store>(() => getStore(jobSeekerSession?.userId))
  const [opportunities, setOpportunities] = useState<Opportunity[]>([])
  const [dataStatus, setDataStatus] = useState<OpportunityLoadStatus>('loading')
  const [lastRefresh, setLastRefresh] = useState<Date | null>(null)
  const [adminSession, setAdminSession] = useState<AdminSession | null>(null)
  const [page, setPage] = useState<Page>(() => getSavedJobSeekerSession() ? 'home' : 'auth')
  const [selected, setSelected] = useState<Opportunity | null>(null)
  const [filter, setFilter] = useState('All')
  const [query, setQuery] = useState('')
  const [toast, setToast] = useState('')
  const [confirmation, setConfirmation] = useState<ConfirmationConfig | null>(null)
  const [question, setQuestion] = useState(questions[0].title)
  const [answer, setAnswer] = useState('')
  const [feedback, setFeedback] = useState(false)
  const [menuOpen, setMenuOpen] = useState(false)
  useEffect(() => { if (jobSeekerSession && storeOwnerId === jobSeekerSession.userId) localStorage.setItem(`${STORE_KEY_PREFIX}${encodeURIComponent(jobSeekerSession.userId)}`, JSON.stringify(store)) }, [store, jobSeekerSession?.userId, storeOwnerId])
  useEffect(() => { if (!jobSeekerSession) { setStoreOwnerId(null); setStore(getStore()) } }, [jobSeekerSession?.userId])
  useEffect(() => { if (jobSeekerSession) sessionStorage.setItem('thusapath-auth-session', JSON.stringify(jobSeekerSession)); else sessionStorage.removeItem('thusapath-auth-session') }, [jobSeekerSession])
  useEffect(() => { if (!jobSeekerSession) return; const timer = window.setTimeout(() => setJobSeekerSession(null), Math.max(0, jobSeekerSession.expiresAt - Date.now())); return () => window.clearTimeout(timer) }, [jobSeekerSession])
  const refreshListings = async () => { setDataStatus('loading'); const result = await loadOpportunities(); setOpportunities(result.opportunities); setDataStatus(result.status); setLastRefresh(new Date()) }
  useEffect(() => { void refreshListings() }, [])
  useEffect(() => { if (!toast) return; const timer = window.setTimeout(() => setToast(''), 3000); return () => window.clearTimeout(timer) }, [toast])
  const listings = useMemo(() => opportunities.filter(item => (filter === 'All' || item.category === filter) && `${item.title} ${item.organisation} ${item.place} ${item.category}`.toLowerCase().includes(query.toLowerCase())).sort((a,b)=>profileFit(b,store.profile)-profileFit(a,store.profile)), [opportunities, filter, query, store.profile])
  const openPage = (next: Page) => { setPage(next); setSelected(null); setMenuOpen(false); window.scrollTo({ top: 0, behavior: 'smooth' }) }
  const signInJobSeekerToApp = (session: AdminSession) => { setStore(getStore(session.userId)); setStoreOwnerId(session.userId); setJobSeekerSession(session); openPage('home'); setToast('You’re signed in.') }
  const updateStore = (change: Partial<Store>) => setStore(current => ({ ...current, ...change }))
  const requestConfirmation = (config:ConfirmationConfig) => setConfirmation(config)
  const submitReport = async (report: {opportunityId:string;reason:string;note:string}, item: Opportunity) => {
    updateStore({ reports: [...store.reports, { ...report, id: `report-${Date.now()}`, createdAt: new Date().toISOString() }] })
    setSelected(null)
    if (!jobSeekerSession) { setToast('Sign in to send a safety report to ThusaPath.'); return }
    try {
      await sendOpportunityReport(jobSeekerSession, item, report.reason, report.note)
      setToast('Your report has been sent to ThusaPath for review.')
    } catch {
      setToast('We could not send your report. It is saved only on this device for now.')
    }
  }
  const signOut = () => requestConfirmation({ title:'Sign out of ThusaPath?', message:'Your saved progress stays private to your account on this device. You can sign back in at any time.', confirmLabel:'Sign out', onConfirm:() => { setJobSeekerSession(null); setAdminSession(null); setStoreOwnerId(null); setStore(getStore()); setConfirmation(null); openPage('auth'); setToast('You’re signed out.') } })
  const toggleSaved = (id: string) => updateStore({ saved: store.saved.includes(id) ? store.saved.filter(value => value !== id) : [...store.saved, id] })
  const completeTask = (id: string) => { if (!store.completed.includes(id)) updateStore({ completed: [...store.completed, id] }); setToast('Nice work. Your progress is saved.') }
  const nav = [ { id:'home' as Page, label:'Home', icon:Home }, { id:'path' as Page, label:'My Path', icon:ArrowUpRight }, { id:'opportunities' as Page, label:'Find opportunities', icon:Compass }, { id:'goals' as Page, label:'My goals', icon:CheckCircle2 }, { id:'coach' as Page, label:'Interview practice', icon:MessageCircle }, { id:'cv' as Page, label:'CV Studio', icon:FileText }, { id:'profile' as Page, label:'My profile', icon:UserRound } ]
  return <div className="app-shell">
    {page !== 'auth'&&<header className="mobile-header"><button className="icon-button" onClick={() => setMenuOpen(!menuOpen)} aria-label="Open menu"><Menu size={21}/></button><Brand onClick={() => openPage('home')}/><button className="avatar small" onClick={() => openPage('profile')}>{store.profile.name[0]}</button></header>}
    {page !== 'auth'&&<aside className={`sidebar ${menuOpen ? 'sidebar-open' : ''}`}>
      <Brand onClick={() => openPage('home')}/>
      <div className="side-caption">YOUR SPACE</div>
      <nav aria-label="Main menu">{nav.map(({ id,label,icon:Icon }) => <button key={id} className={`nav-item ${page === id ? 'active' : ''}`} onClick={() => openPage(id)}><Icon size={19} strokeWidth={1.9}/><span>{label}</span>{id === 'opportunities' && <span className="nav-count">{opportunities.length}</span>}</button>)}</nav>
      <button className="sidebar-user" onClick={() => { if (jobSeekerSession || adminSession) signOut(); else openPage('auth') }}><span className="avatar">{(jobSeekerSession?.email || adminSession?.email || store.profile.name || 'T')[0].toUpperCase()}</span><span className="user-label"><b>{jobSeekerSession?.email || adminSession?.email || store.profile.name || 'Your account'}</b><small>{jobSeekerSession || adminSession ? 'Sign out' : 'Sign in / Register'}</small></span>{jobSeekerSession || adminSession ? <LogOut size={15}/> : <ArrowRight size={15}/>}</button>
    </aside>}
    <main className={`main-area ${page==='auth'?'auth-main-area':''}`}>
      <div className="content-wrap">
        {page === 'auth' && <AuthPage onAdminSignIn={session => { setAdminSession(session); openPage('admin') }} onUserSignIn={signInJobSeekerToApp} />}
        {page === 'admin' && (adminSession ? <AdminDashboard session={adminSession} listings={opportunities} status={dataStatus} lastRefresh={lastRefresh} onRefresh={() => void refreshListings()} onLogout={signOut} /> : <AuthPage onAdminSignIn={session => { setAdminSession(session); openPage('admin') }} onUserSignIn={signInJobSeekerToApp} />)}
        {page === 'home' && <HomePage profile={store.profile} listings={opportunities} dataStatus={dataStatus} saved={store.saved} completed={store.completed} onReload={() => void refreshListings()} onOpenPage={openPage} onSelect={setSelected} onSave={toggleSaved} />}
        {page === 'opportunities' && <OpportunitiesPage listings={listings} profile={store.profile} dataStatus={dataStatus} onReload={() => void refreshListings()} filter={filter} query={query} saved={store.saved} onFilter={setFilter} onQuery={setQuery} onSelect={setSelected} onSave={toggleSaved} />}
        {page === 'path' && <>{dataStatus !== 'live' && <LiveDataNotice status={dataStatus} onRetry={() => void refreshListings()} />}<PathPage listings={opportunities} profile={store.profile} saved={store.saved} completed={store.completed} applied={store.applied} onSelect={setSelected} onComplete={completeTask} onCoach={() => openPage('coach')} onEditProfile={() => openPage('profile')} /></>}
        {page === 'goals' && <GoalsPage goals={store.goals} opportunities={opportunities} onSave={goals => updateStore({ goals })} onToast={setToast} />}
        {page === 'coach' && <CoachPage question={question} answer={answer} feedback={feedback} questions={questions} profile={store.profile} history={store.answers} onQuestion={value => { setQuestion(value); setFeedback(false) }} onAnswer={setAnswer} onPractice={() => { if (!answer.trim()) return; setFeedback(true); updateStore({ answers: [{ question, answer: answer.trim(), date: new Date().toISOString() }, ...store.answers].slice(0, 10) }); if (!store.completed.includes('interview-practice')) updateStore({ completed: [...store.completed, 'interview-practice'] }) }} onClear={() => { setAnswer(''); setFeedback(false) }} onDeleteHistory={() => requestConfirmation({ title:'Clear your practice history?', message:'This will remove all of your saved interview practice answers from this device.', confirmLabel:'Clear history', onConfirm:() => { updateStore({ answers: [] }); setConfirmation(null); setToast('Your practice history has been cleared.') } })} />}
        {page === 'profile' && <ProfilePage profile={store.profile} onSave={profile => { updateStore({ profile, completed: store.completed.includes('profile-check') ? store.completed : [...store.completed, 'profile-check'] }); setToast('Your profile has been updated.') }} />}
        {page === 'cv' && <CVPage profile={store.profile} cvs={store.cvs} onSave={cvs => updateStore({ cvs })} onToast={setToast} onConfirmAction={requestConfirmation} />}
      </div>
      <footer className="footer"><span>ThusaPath <span className="footer-heart">♥</span> Made to help you take the next step.</span><div className="footer-links"><span>Need help? Send an email to <b>admin@thusaPath.com</b></span></div></footer>
    </main>
    {selected && <OpportunityModal item={selected} profile={store.profile} saved={store.saved.includes(selected.id)} applied={store.applied.includes(selected.id)} reportCount={store.reports.filter(report=>report.opportunityId===selected.id).length} onReport={report=>{void submitReport(report,selected)}} onClose={() => setSelected(null)} onSave={() => toggleSaved(selected.id)} onApply={() => { if (!store.applied.includes(selected.id)) updateStore({ applied: [...store.applied, selected.id] }); setSelected(null); setToast('We saved this opportunity on your device. Finish the application on the employer’s site.')}} onPath={() => { if (!store.saved.includes(selected.id)) toggleSaved(selected.id); setSelected(null); openPage('path') }} />}
    {toast && <div className="toast" role="status"><CheckCircle2 size={17}/>{toast}<button aria-label="Dismiss" onClick={() => setToast('')}><X size={15}/></button></div>}
    {confirmation && <ConfirmationModal config={confirmation} onCancel={() => setConfirmation(null)} />}
  </div>
}

function Brand({ onClick }: { onClick: () => void }) { return <button className="brand" onClick={onClick}><span className="brand-mark"><span/><span/><span/></span><span className="brand-word">thusa<span>path</span></span></button> }

function ConfirmationModal({config,onCancel}:{config:ConfirmationConfig;onCancel:()=>void}) {
  useEffect(() => {
    const closeOnEscape = (event:KeyboardEvent) => { if(event.key==='Escape') onCancel() }
    window.addEventListener('keydown',closeOnEscape)
    return () => window.removeEventListener('keydown',closeOnEscape)
  },[onCancel])
  return <div className="confirm-backdrop" onMouseDown={event=>{if(event.target===event.currentTarget)onCancel()}}><section className="confirm-dialog" role="alertdialog" aria-modal="true" aria-labelledby="confirm-title" aria-describedby="confirm-message"><span className="confirm-icon">{config.confirmLabel==='Sign out'?<LogOut size={19}/>:<Trash2 size={19}/>}</span><h2 id="confirm-title">{config.title}</h2><p id="confirm-message">{config.message}</p><div className="confirm-actions"><button className="btn btn-outline" onClick={onCancel} autoFocus>Cancel</button><button className={`btn ${config.confirmLabel==='Sign out'?'btn-dark':'btn-danger'}`} onClick={()=>{config.onConfirm();onCancel()}}>{config.confirmLabel}</button></div></section></div>
}

function LiveDataNotice({status,onRetry}:{status:OpportunityLoadStatus;onRetry:()=>void}) {
  const copy = {
    loading: ['Checking for opportunities','This can take a moment. Your details stay on this device.'],
    unconfigured: ['No opportunities to show yet','New opportunities will appear here when they are available.'],
    error: ['We can’t reach the listings right now','Please try again in a little while. We haven’t shown sample jobs as real ones.'],
    empty: ['There are no current opportunities yet','Check back soon. New listings will appear here when they are available.'],
    live: ['', ''],
  } as const
  const [title,description]=copy[status]
  if(status==='live') return null
  return <section className="empty-state live-data-notice" aria-live="polite"><span className="empty-icon">{status==='loading'?<Search size={23}/>:<Info size={23}/>}</span><h3>{title}</h3><p>{description}</p>{(status==='error'||status==='loading')&&<button className="btn btn-dark" onClick={onRetry}>{status==='loading'?'Check again':'Try again'}</button>}</section>
}

function VerificationUnavailableNotice() { return <><div className="safety-hero external-source-hero"><span><Info size={21}/></span><div><b>We could not load the verification record</b><p>Do not treat this employer as checked. Confirm the organisation through an official contact channel before sharing details or travelling.</p></div></div><div className="safety-reminder"><Info size={16}/><span>The AI safety check looks for warning signs in the advert. It cannot prove that an employer is genuine.</span></div></> }

function ExternalSourceNotice() {
  return <><div className="safety-hero external-source-hero"><span><ShieldCheck size={22}/></span><div><b>Shared job listing</b><p>ThusaPath has not independently checked this employer or the full advert. The AI check looks for warning signs in the details we received; it cannot guarantee a job is safe.</p></div></div><div className="safety-reminder"><Info size={16}/><span>Never pay to apply or secure a job. Do not share your ID or bank details before checking who is asking and why.</span></div></>
}

function PageHeading({ eyebrow, title, description, right }: { eyebrow?: string; title: string; description?: string; right?: React.ReactNode }) { return <div className="page-heading"><div>{eyebrow && <div className="eyebrow">{eyebrow}</div>}<h1>{title}</h1>{description && <p>{description}</p>}</div>{right}</div> }

function HomePage({ profile, listings, dataStatus, saved, completed, onReload, onOpenPage, onSelect, onSave }: { profile:Profile; listings:Opportunity[]; dataStatus:OpportunityLoadStatus; saved:string[]; completed:string[]; onReload:()=>void; onOpenPage:(page:Page)=>void; onSelect:(item:Opportunity)=>void; onSave:(id:string)=>void }) {
  const firstName = profile.name.split(' ')[0] || 'there'
  const picks = [...listings].sort((a,b)=>profileFit(b,profile)-profileFit(a,profile) || Number(isBeginnerFriendly(b))-Number(isBeginnerFriendly(a))).slice(0,3)
  return <>
    <section className="welcome-card"><div className="welcome-copy"><div className="eyebrow light-eyebrow"><span className="sun-dot"/> A new day, a new possibility</div><h1>Hi {firstName}, your next<br className="desktop-break"/> step is within reach.</h1><p>Find a real opportunity. See what you need. Take it one step at a time.</p><button className="btn btn-light" onClick={() => onOpenPage('opportunities')}>Find opportunities <ArrowRight size={16}/></button><div className="welcome-note"><ShieldCheck size={15}/> Check safety details before you apply</div></div><div className="welcome-art" aria-hidden="true"><div className="art-sun"/><div className="art-path"/><div className="art-hill hill-back"/><div className="art-hill hill-front"/><div className="art-star star-one">✳</div><div className="art-star star-two">✦</div><div className="art-pin"><MapPin size={22}/></div><div className="art-label">Your path<br/>starts here</div></div></section>
    <div className="quick-stats"><div className="stat-card"><span className="stat-icon stat-mint"><Compass size={19}/></span><span className="stat-copy"><b>{listings.length} opportunities</b><small>to explore near you</small></span><button onClick={() => onOpenPage('opportunities')} aria-label="Explore opportunities"><ArrowUpRight size={17}/></button></div><div className="stat-card"><span className="stat-icon stat-lilac"><Bookmark size={18}/></span><span className="stat-copy"><b>{saved.length} saved</b><small>ready when you are</small></span><button onClick={() => onOpenPage('path')} aria-label="View saved opportunities"><ArrowUpRight size={17}/></button></div><div className="stat-card"><span className="stat-icon stat-peach"><CheckCircle2 size={18}/></span><span className="stat-copy"><b>{completed.length} steps done</b><small>every step counts</small></span><button onClick={() => onOpenPage('path')} aria-label="View your path"><ArrowUpRight size={17}/></button></div></div>
    {dataStatus !== 'live' ? <LiveDataNotice status={dataStatus} onRetry={onReload} /> : picks.length ? <section className="section-block"><div className="section-heading"><div><div className="eyebrow">PICKED FOR YOU</div><h2>Good places to start</h2><p>These may suit what you’ve told us about yourself.</p></div><button className="text-link" onClick={() => onOpenPage('opportunities')}>See all <ArrowRight size={15}/></button></div><div className="opportunity-grid">{picks.map(item=><OpportunityCard key={item.id} item={item} profile={profile} saved={saved.includes(item.id)} onSelect={()=>onSelect(item)} onSave={()=>onSave(item.id)}/>)}</div></section> : <section className="section-block"><div className="section-heading"><div><div className="eyebrow">LIVE OPPORTUNITIES</div><h2>See the latest listings</h2><p>Each listing shows its safety status and advert details.</p></div><button className="text-link" onClick={() => onOpenPage('opportunities')}>Browse listings <ArrowRight size={15}/></button></div></section>}
    <section className="next-step-banner"><span className="next-step-icon"><MessageCircle size={20}/></span><div><span className="eyebrow">A LITTLE PRACTICE GOES A LONG WAY</span><h3>Want to feel more ready for an interview?</h3><p>Try a question and get simple tips to help you answer.</p></div><button className="btn btn-dark" onClick={()=>onOpenPage('coach')}>Practise an answer <ArrowRight size={15}/></button></section>
    <section className="journey-strip"><div className="journey-title"><span className="eyebrow">YOUR JOURNEY</span><span>There’s no rush. Start anywhere.</span></div><button onClick={()=>onOpenPage('opportunities')}><span className="journey-step step-one">01</span><span><b>Find something real</b><small>See where each listing came from</small></span><ArrowRight size={15}/></button><button onClick={()=>onOpenPage('path')}><span className="journey-step step-two">02</span><span><b>See your next steps</b><small>Learn what you need and how to get there</small></span><ArrowRight size={15}/></button><button onClick={()=>onOpenPage('coach')}><span className="journey-step step-three">03</span><span><b>Practise with confidence</b><small>Try interview questions in your own time</small></span><ArrowRight size={15}/></button></section>
  </>
}

function OpportunitiesPage({ listings, profile, dataStatus, onReload, filter, query, saved, onFilter, onQuery, onSelect, onSave }: {listings:Opportunity[];profile:Profile;dataStatus:OpportunityLoadStatus;onReload:()=>void;filter:string;query:string;saved:string[];onFilter:(v:string)=>void;onQuery:(v:string)=>void;onSelect:(o:Opportunity)=>void;onSave:(id:string)=>void}) {
  const filters = ['All','Job','Learnership','Internship','Training','Volunteering','Bursary']
  const pageSize = 6
  const [showMap,setShowMap]=useState(false)
  const [audienceFilter,setAudienceFilter]=useState<'all'|'beginner'|'fit'>('all')
  const [currentPage,setCurrentPage]=useState(1)
  const audienceListings=listings.filter(item=>audienceFilter==='beginner'?isBeginnerFriendly(item):audienceFilter==='fit'?profileFit(item,profile)>0:true)
  const pageCount=Math.max(1,Math.ceil(audienceListings.length/pageSize))
  const visibleListings=audienceListings.slice((currentPage-1)*pageSize,currentPage*pageSize)
  const firstListing=audienceListings.length?(currentPage-1)*pageSize+1:0
  const lastListing=Math.min(currentPage*pageSize,audienceListings.length)
  const markerIcon=L.divIcon({className:'custom-map-marker',html:'<span class="pin-core"></span>',iconSize:[26,34],iconAnchor:[13,31]})
  const mappedListings=audienceListings.filter((item):item is Opportunity & {coordinates:[number,number]}=>Boolean(item.coordinates))
  useEffect(()=>setCurrentPage(1),[listings,filter,query,audienceFilter])
  const changePage=(next:number)=>{setCurrentPage(next);document.querySelector('.opportunity-grid')?.scrollIntoView({behavior:'smooth',block:'start'})}
  return <>
    <PageHeading eyebrow="YOUR NEXT OPPORTUNITY" title="Find something that fits" description="We put roles that match your profile first. Try the beginner filter if you’re new to work." right={<div className="heading-actions"><button className="map-toggle" onClick={()=>setShowMap(!showMap)} disabled={!mappedListings.length}><MapPin size={14}/>{showMap?'Show list':'Show map'}</button><span className="results-pill"><span className="green-dot"/>{audienceListings.length} to explore</span></div>}/>
    <LiveDataNotice status={dataStatus} onRetry={onReload}/>
    <div className="search-row"><div className="search-box"><Search size={18}/><input value={query} onChange={e=>onQuery(e.target.value)} placeholder="Try ‘shop’, ‘training’ or your area" aria-label="Search opportunities"/>{query&&<button onClick={()=>onQuery('')} aria-label="Clear search"><X size={16}/></button>}</div><button className="nearby-pill" disabled><MapPin size={15}/> Choose an area <ChevronDown size={14}/></button></div>
    <div className="filter-row">{filters.map(value=><button key={value} className={`filter-chip ${filter===value?'selected':''}`} onClick={()=>onFilter(value)}>{value}</button>)}</div>
    <div className="audience-filter-row"><button className={audienceFilter==='all'?'selected':''} onClick={()=>setAudienceFilter('all')}>All opportunities</button><button className={audienceFilter==='beginner'?'selected':''} onClick={()=>setAudienceFilter(audienceFilter==='beginner'?'all':'beginner')}>Good for beginners</button><button className={audienceFilter==='fit'?'selected':''} disabled={!profile.skills.length&&!profile.education&&!profile.location} onClick={()=>setAudienceFilter(audienceFilter==='fit'?'all':'fit')}>Matches my profile</button></div>
    {audienceListings.length?(showMap?<><div className="map-legend"><span><i/> Opportunity location</span><span>Only listings with a location are shown</span></div><MapContainer className="opportunity-map" center={mappedListings[0]?.coordinates ?? [-29,24]} zoom={mappedListings.length===1?10:5} scrollWheelZoom={false}><TileLayer attribution='&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors' url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"/>{mappedListings.map(item=><Marker key={item.id} position={item.coordinates} icon={markerIcon}><Popup><div className="map-popup"><strong>{item.title}</strong><span>{item.organisation}</span><small>{item.category}</small><button onClick={()=>onSelect(item)}>See this opportunity <ArrowRight size={13}/></button></div></Popup></Marker>)}</MapContainer></>:<><div className="opportunity-grid all-listings">{visibleListings.map(item=><OpportunityCard key={item.id} item={item} profile={profile} saved={saved.includes(item.id)} onSelect={()=>onSelect(item)} onSave={()=>onSave(item.id)}/>)}</div>{audienceListings.length>pageSize&&<nav className="listing-pagination" aria-label="Job listing pages"><span>Showing <b>{firstListing}–{lastListing}</b> of {audienceListings.length}</span><div><button className="btn btn-outline" onClick={()=>changePage(Math.max(1,currentPage-1))} disabled={currentPage===1}><ArrowLeft size={14}/> Previous</button><span>Page <b>{currentPage}</b> of {pageCount}</span><button className="btn btn-outline" onClick={()=>changePage(Math.min(pageCount,currentPage+1))} disabled={currentPage===pageCount}>Next <ArrowRight size={14}/></button></div></nav>}</>):<div className="empty-state"><span className="empty-icon"><Search size={23}/></span><h3>{audienceFilter==='beginner'?'No beginner-friendly matches right now':'No matches yet'}</h3><p>{audienceFilter==='beginner'?'Try all opportunities too. Some adverts do not say whether experience is needed.':'Try another word or choose a different type of opportunity.'}</p><button className="btn btn-dark" onClick={()=>{setAudienceFilter('all');onQuery('');onFilter('All')}}>Show all opportunities</button></div>}
    <div className="official-links"><b>More places to look for youth opportunities</b><a href="https://www.sayouth.org.za/" target="_blank" rel="noreferrer">SA Youth <ArrowUpRight size={13}/></a><a href="https://essa.labour.gov.za/EssaOnline/WebBeans/" target="_blank" rel="noreferrer">Employment Services of South Africa <ArrowUpRight size={13}/></a><a href="https://www.gov.za/about-government/government-jobs" target="_blank" rel="noreferrer">Government jobs <ArrowUpRight size={13}/></a></div>
    <div className="estimate-note"><Info size={15}/> Confirm the exact venue and travel details on the application page before you go.</div>
  </>
}
function getAdvertRequirements(item: Opportunity, profile: Profile) {
  const normalize = (value: string) => value.toLocaleLowerCase().replace(/[^a-z0-9]+/g, ' ').trim()
  const education=normalize(profile.education); const educationAliases=/grade 12|matric/.test(education)?['grade 12','matric']:[]; const profileWords = [profile.education, ...profile.skills, ...educationAliases].map(normalize).filter(Boolean)
  return [...advertSkills(item).map(skill => `Skill: ${skill}`), ...advertRequirements(item)].map(label => ({ label, met: profileWords.some(word => normalize(label).includes(word) || word.includes(normalize(label))) }))
}

function OpportunityCard({ item, profile, saved, onSelect, onSave }: {item:Opportunity;profile:Profile;saved:boolean;onSelect:()=>void;onSave:()=>void}) {
  const cardRequirements=getAdvertRequirements(item,profile)
  const met=cardRequirements.filter(req=>req.met).length
  return <article className="op-card"><div className="card-top"><span className={`org-avatar ${item.colour}`}>{item.initials}</span><button className={`save-button ${saved?'is-saved':''}`} onClick={onSave} aria-label={saved?'Remove from saved':'Save opportunity'}><Bookmark size={17} fill={saved?'currentColor':'none'}/></button></div><div className="card-kicker"><span>{item.category}</span><span className="kicker-sep">·</span><span>{item.closing==='See source'?item.closing:`Closes ${item.closing}`}</span></div><button className="card-title-button" onClick={onSelect}><h3>{item.title}</h3></button><div className="card-org">{item.organisation} {item.verifiedByUs===true&&<ShieldCheck size={14} fill="#dff3e9"/>}</div><div className="card-location"><MapPin size={14}/><span>{item.place}</span>{item.distance!==undefined&&<><span className="kicker-sep">·</span>{item.distance} km away</>}</div><div className="card-pay">{item.pay}</div>{isBeginnerFriendly(item)&&<div className="beginner-badge"><Sparkles size={13}/>Good place to start</div>}{cardRequirements.length>0&&<div className="match-row"><span className="match-bar"><span style={{width:`${Math.round(met/cardRequirements.length*100)}%`}}/></span><span>{met} of {cardRequirements.length} advert points match</span></div>}<div className="card-bottom">{item.verifiedByUs===true&&<span className="safety-mini"><ShieldCheck size={14}/> ThusaPath checked</span>}{item.sourceName==='Adzuna'&&<a className="provider-attribution card-provider-attribution adzuna-credit" href={item.sourceUrl} target="_blank" rel="noreferrer">Adzuna</a>}{item.sourceName==='YubHub'&&<a className="provider-attribution card-provider-attribution" href={item.sourceUrl} target="_blank" rel="noreferrer">Data by YubHub</a>}<button onClick={onSelect}>See details <ArrowRight size={14}/></button></div></article>
}

function OpportunityModal({ item, profile, saved, applied, reportCount, onReport, onClose, onSave, onApply, onPath }: {item:Opportunity;profile:Profile;saved:boolean;applied:boolean;reportCount:number;onReport:(report:{opportunityId:string;reason:string;note:string})=>void;onClose:()=>void;onSave:()=>void;onApply:()=>void;onPath:()=>void}) {
  const requirements = getAdvertRequirements(item, profile)
  const ready = requirements.filter(req=>req.met).length
  const [tab,setTab] = useState<'details'|'safety'>('details')
  const [reporting,setReporting] = useState(false)
  const [reason,setReason] = useState('')
  const [note,setNote] = useState('')
  const [safetyResult,setSafetyResult] = useState<ScamCheckResult|null>(null)
  const [safetyError,setSafetyError] = useState('')
  const [checkingSafety,setCheckingSafety] = useState(false)
  useEffect(()=>{setSafetyResult(null);setSafetyError('');setCheckingSafety(false)},[item.id])
  const runSafetyCheck=async()=>{setCheckingSafety(true);setSafetyError('');try{setSafetyResult(await checkJobSafety(item))}catch(error){setSafetyError(error instanceof Error?error.message:'Could not complete the safety check.')}finally{setCheckingSafety(false)}}
  return <div className="modal-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)onClose()}}>
    <section className="detail-modal" role="dialog" aria-modal="true" aria-label={item.title}>
      <div className="modal-head"><span className="eyebrow">OPPORTUNITY DETAILS</span><button className="icon-button" onClick={onClose} aria-label="Close"><X size={20}/></button></div>
      <div className="detail-intro"><span className={`org-avatar large ${item.colour}`}>{item.initials}</span><div><div className="card-org">{item.organisation} {item.verifiedByUs===true&&<ShieldCheck size={14} fill="#dff3e9"/>}</div><h2>{item.title}</h2><div className="card-location"><MapPin size={14}/>{item.place}{item.distance!==undefined&&<><span className="kicker-sep">·</span>{item.distance} km away</>}</div></div></div>
      <div className="detail-tabs"><button className={tab==='details'?'active':''} onClick={()=>{setTab('details');setReporting(false)}}>About this role</button><button className={tab==='safety'?'active':''} onClick={()=>setTab('safety')}>Safety check</button></div>
      {tab==='details'?<div className="detail-body"><div className="detail-facts"><span><b>{item.pay}</b><small>Pay or support</small></span><span><b>{item.category}</b><small>Type</small></span><span><b>{item.closing}</b><small>{item.closing==='See source'?'Closing date':'Apply by'}</small></span></div><p className="detail-description">{item.description}</p>{item.sourceName==='Adzuna'&&<a className="provider-attribution detail-attribution" href={item.sourceUrl} target="_blank" rel="noreferrer">Adzuna</a>}{item.sourceName==='YubHub'&&<a className="provider-attribution" href={item.sourceUrl} target="_blank" rel="noreferrer">Data by YubHub</a>}<h3>Skills and requirements in the advert</h3>{requirements.length>0?<><div className="requirements-list">{requirements.map(req=><div key={req.label}><span className={req.met?'req-met':'req-missing'}>{req.met?<Check size={13}/>:<ArrowRight size={12}/>}</span><span>{req.label}</span><small>{req.met?'On your profile':'Not on your profile yet'}</small></div>)}</div><div className="match-summary"><span className="match-ring">{ready}/{requirements.length}</span><div><b>{profile.skills.length||profile.education?'Your starting point':'Add your skills to check your fit'}</b><p>{profile.skills.length||profile.education?`${ready} of ${requirements.length} advert points match what you added. Missing from your profile does not mean you cannot apply.`:'We compare your profile with words in the advert. You can still apply if you have not added your details yet.'}</p></div></div><button className="text-action-button" onClick={onPath}>Make a plan for missing skills <ArrowRight size={14}/></button></>:<p className="detail-description">This short listing does not show clear skills or requirements. Read the full advert before deciding whether to apply.</p>}</div>:<div className="detail-body">
        {item.verificationStatus==='unavailable'?<VerificationUnavailableNotice/>:item.verifiedByUs!==true?<ExternalSourceNotice/>:!reporting?<><div className="safety-hero"><span><ShieldCheck size={23}/></span><div><b>ThusaPath checked this employer</b><p>A staff member recorded a check of the employer details. This does not guarantee a particular vacancy or job offer.</p></div></div><div className="safety-list"><SafetyRow label="How the details were checked" value={item.verificationMethod||"Staff review"}/><SafetyRow label="Reviewed on" value={item.verifiedAt?new Date(item.verifiedAt).toLocaleDateString("en-ZA",{day:"numeric",month:"short",year:"numeric"}):"Date not recorded"}/><SafetyRow label="Documents valid until" value={item.verifiedUntil||"Not available"}/><SafetyRow label="Posting safety check" value={item.screened?'Passed':'Needs review'}/><SafetyRow label="Fee to apply" value="None requested"/><SafetyRow label="Reports from users" value={item.reports+reportCount===0?'No reports':`${item.reports+reportCount} report${item.reports+reportCount===1?'':'s'}`}/></div><div className="safety-reminder"><Info size={16}/><span>Never pay to apply, interview or secure a job. Confirm the interview venue with the organisation.</span></div><button className="report-listing-link" onClick={()=>setReporting(true)}>Something doesn’t feel right? <span>Report this listing <ArrowRight size={13}/></span></button></>:<div className="report-form"><button className="report-back" onClick={()=>setReporting(false)}><ArrowLeft size={14}/> Back to safety check</button><h3>What seems wrong?</h3><p>Your report goes to the ThusaPath review team. Please leave out ID numbers, bank details and other private information.</p><div className="report-reasons">{['They asked me to pay money','They asked for private details too soon','The message or interview place seems wrong','Something else'].map(option=><label key={option} className={reason===option?'chosen':''}><input type="radio" name="report-reason" value={option} checked={reason===option} onChange={()=>setReason(option)}/><span>{option}</span></label>)}</div><label className="report-note-label">Anything else? <small>Optional</small><textarea value={note} onChange={e=>setNote(e.target.value)} maxLength={400} placeholder="Tell us what happened. Please leave out private details."/></label><div className="report-demo-note"><Info size={14}/> We’ll attach this report to your account so the review team can follow up if needed.</div><div className="report-form-actions"><button className="btn btn-outline" onClick={()=>{setReporting(false);setReason('');setNote('')}}>Cancel</button><button className="btn btn-dark" disabled={!reason} onClick={()=>onReport({opportunityId:item.id,reason,note:note.trim()})}>Save report <ArrowRight size={14}/></button></div></div>}
      </div>}
      {!reporting&&<><div className="ai-safety-panel"><div className="ai-safety-heading"><span className="ai-safety-icon"><ShieldCheck size={18}/></span><div><b>Check for scam signs before you apply</b><small>An AI checks the advert details we received. It cannot guarantee a job is safe.</small></div></div>{safetyResult&&<div className={`ai-safety-result risk-${safetyResult.risk}`}><b>{safetyResult.risk==='low'?'No clear warning signs found':safetyResult.risk==='caution'?'Some details need a closer look':'Possible scam warning signs'}</b><p>{safetyResult.summary}</p>{safetyResult.warningSigns.length>0&&<ul>{safetyResult.warningSigns.map((sign,index)=><li key={index}>{sign}</li>)}</ul>}<div className="ai-safer-steps">{safetyResult.saferSteps.map((step,index)=><span key={index}><CheckCircle2 size={14}/>{step}</span>)}</div></div>}{safetyError&&<div className="ai-safety-error" role="alert">{safetyError}</div>}{!safetyResult?<button className="btn btn-soft safety-check-button" disabled={checkingSafety} onClick={()=>void runSafetyCheck()}>{checkingSafety?'Checking this advert…':'Check for scam signs'} <ShieldCheck size={15}/></button>:<div className="safety-next-actions">{item.applicationUrl?<a className={`btn ${safetyResult.risk==='high'?'btn-outline':'btn-dark'}`} href={item.applicationUrl} target="_blank" rel="noreferrer" onClick={onApply}>{safetyResult.risk==='high'?'I understand, open application':'Continue to application'} <ArrowUpRight size={14}/></a>:<button className="btn btn-dark" onClick={onApply} disabled={applied}>{applied?'Interest saved':'Save interest'} <ArrowRight size={14}/></button>}<button className="text-action-button" disabled={checkingSafety} onClick={()=>void runSafetyCheck()}>Check again</button></div>}<div className="ai-safety-footnote">Your profile is not sent for this check. A low risk result does not mean the employer is verified.</div></div><div className="modal-footer"><button className={`btn btn-outline ${saved?'saved-outline':''}`} onClick={onSave}><Bookmark size={16} fill={saved?'currentColor':'none'}/>{saved?'Saved':'Save'}</button>{tab==='details'&&requirements.length>0&&<button className="btn btn-soft" onClick={onPath}>See my steps <ArrowRight size={15}/></button>}</div></>}
    </section>
  </div>
}

function SafetyRow({ label,value }: {label:string;value:string}) { return <div><span className="safety-check"><Check size={13}/></span><span>{label}</span><b>{value}</b></div> }

type SkillPractice = { prompt:string; choices:{label:string;feedback:string}[] }
function getSkillPractice(skill:string): SkillPractice {
  const value=skill.toLowerCase()
  if(/customer|communication|people skills|telephone|sales/.test(value)) return { prompt:'A customer is unsure which item they need. What is a helpful first step?', choices:[{label:'Ask what they need and listen carefully',feedback:'Listening first helps you understand what the person needs before offering help.'},{label:'Show them where the items are',feedback:'Showing someone where to look can help. You can also ask a question first so you guide them to the right place.'},{label:'Guess what they need and choose for them',feedback:'It is safer to ask before deciding. This gives the customer a chance to explain.'}] }
  if(/computer|excel|data entry|typing|administration|office/.test(value)) return { prompt:'You are entering information into a work record. What helps avoid mistakes?', choices:[{label:'Check the details against the original before saving',feedback:'Checking names and numbers against the original helps catch small mistakes.'},{label:'Fill in anything that is missing by guessing',feedback:'Don’t guess missing information. Ask the right person or leave it blank if that is the workplace process.'},{label:'Save quickly without reading it again',feedback:'A quick final check is a useful habit when working with records.'}] }
  if(/numeracy|cash handling|stock control|attention to detail/.test(value)) return { prompt:'You have counted items or money and the number does not match the record. What should you do?', choices:[{label:'Count again and tell the person in charge if it still differs',feedback:'Rechecking and speaking up helps the team find a mistake before it causes a bigger problem.'},{label:'Change the record to make the numbers match',feedback:'Keep the original information honest. Recheck it and ask a supervisor to help resolve the difference.'},{label:'Ignore it because the difference is small',feedback:'Even a small difference can matter. It is better to check and let the right person know.'}] }
  if(/teamwork|problem solving|organisation|time management/.test(value)) return { prompt:'Your team has several tasks to finish before closing. What is a useful next step?', choices:[{label:'Ask what is most urgent and agree who will do each task',feedback:'Agreeing on priorities and sharing tasks helps everyone know what to do next.'},{label:'Start everything at once by yourself',feedback:'It is good to be willing, but checking priorities and sharing work can prevent confusion.'},{label:'Wait without telling anyone you are unsure',feedback:'If you are unsure, asking a clear question helps the team plan.'}] }
  if(/cleaning|food handling|cooking|first aid|security/.test(value)) return { prompt:'You notice something that could make a person or workplace unsafe. What should you do?', choices:[{label:'Follow the safety steps you were taught and tell the person in charge',feedback:'Following the workplace safety steps and reporting the concern helps protect people.'},{label:'Ignore it because it is not your task',feedback:'Safety concerns should be raised, even when they are outside your usual task.'},{label:'Try an unfamiliar fix without asking',feedback:'Do not try a fix you have not been trained to do. Use the agreed safety steps and ask for help.'}] }
  return { prompt:`Think about a task where you could use ${skill}. What is a careful first step?`, choices:[{label:'Check what is needed and ask if anything is unclear',feedback:`Getting clear on the task is a useful way to practise ${skill}.`},{label:'Start before checking the instructions',feedback:'Taking a moment to understand the task can prevent avoidable mistakes.'},{label:'Ask someone to do the whole task for you',feedback:'You can ask for guidance, then try a manageable part yourself.'}] }
}

function PathPage({ listings,profile,saved,completed,applied,onSelect,onComplete,onCoach,onEditProfile }: {listings:Opportunity[];profile:Profile;saved:string[];completed:string[];applied:string[];onSelect:(o:Opportunity)=>void;onComplete:(id:string)=>void;onCoach:()=>void;onEditProfile:()=>void}) {
  const [quizOpen,setQuizOpen]=useState(false)
  const [quizAnswer,setQuizAnswer]=useState('')
  const [quizResult,setQuizResult]=useState(false)
  const active = listings.find(item=>saved.includes(item.id)&&getAdvertRequirements(item,profile).length>0) || listings.find(item=>getAdvertRequirements(item,profile).length>0)
  if (!active) return <><PageHeading eyebrow="YOUR NEXT STEPS" title="Your Path" description="Small steps can bring you closer to an opportunity."/><div className="empty-state"><span className="empty-icon"><Compass size={23}/></span><h3>Save an opportunity to begin</h3><p>Your step-by-step plan will use the skills and requirements from the listing you choose.</p></div></>
  const activeRequirements=getAdvertRequirements(active,profile)
  const focusSkill=advertSkills(active)[0]||activeRequirements[0]?.label||'a useful skill'
  const skillPractice=getSkillPractice(focusSkill)
  const doneCount = completed.length
  const tasks = [{id:'profile-check',label:'Add a little about yourself',sub:'Let employers see what you enjoy and what you can do.',action:'Update profile',done:completed.includes('profile-check')},{id:'skill-task',label:`Practise: ${focusSkill}`,sub:`A quick activity to help with “${active.title}”.`,action:'Try a quick task',done:completed.includes('skill-task')},{id:'interview-practice',label:'Practise one interview answer',sub:'Try a question in the Interview Coach.',action:'Practise now',done:completed.includes('interview-practice') }]
  return <><PageHeading eyebrow="YOUR NEXT STEPS" title="Your Path" description="Small steps can bring you closer to an opportunity." right={<div className="progress-summary"><div className="progress-ring" style={{'--progress':`${Math.min(doneCount/3*100,100)}%`} as React.CSSProperties}><span>{Math.min(doneCount,3)}<small>/3</small></span></div><span><b>Your progress</b><small>Every step counts</small></span></div>}/><div className="path-opportunity"><div className="path-op-top"><span className="eyebrow">A PLACE YOU SAVED</span><button onClick={()=>onSelect(active)}>View opportunity <ArrowUpRight size={14}/></button></div><div className="path-op-main"><span className={`org-avatar ${active.colour}`}>{active.initials}</span><div><h3>{active.title}</h3><p>{active.organisation} <span>·</span> {active.place}</p></div><div className="readiness"><span className="readiness-value">{Math.round(activeRequirements.filter(req=>req.met).length/activeRequirements.length*100)}%</span><span>match today</span></div></div><div className="path-match-bar"><span style={{width:`${Math.round(activeRequirements.filter(req=>req.met).length/activeRequirements.length*100)}%`}}/></div><div className="path-match-note"><span>You already meet {activeRequirements.filter(req=>req.met).length} of {activeRequirements.length} needs</span><button onClick={()=>onSelect(active)}>See what’s needed <ArrowRight size={14}/></button></div></div><div className="path-layout"><section className="path-steps"><div className="section-heading compact"><div><div className="eyebrow">YOUR SIMPLE PLAN</div><h2>One step at a time</h2></div><span className="step-count">{Math.min(doneCount,3)} of 3 done</span></div>{tasks.map((task,i)=><article key={task.id} className={`task-card ${completed.includes(task.id)?'task-done':''}`}><div className="task-index">{completed.includes(task.id)?<Check size={17}/>:String(i+1).padStart(2,'0')}</div><div className="task-copy"><h3>{task.label}</h3><p>{task.sub}</p></div>{completed.includes(task.id)?<span className="done-label"><CheckCircle2 size={15}/> Done</span>:<button className="btn btn-soft task-action" onClick={()=>task.id==='profile-check'?onEditProfile():task.id==='interview-practice'?onCoach():setQuizOpen(true)}>{task.action}<ArrowRight size={14}/></button>}</article>)}<div className="progress-reassurance"><Heart size={17}/><span>You don’t need to have everything figured out. You’re building your next step as you go.</span></div></section><aside className="requirements-card"><div className="eyebrow">WHAT THIS ROLE NEEDS</div><h3>Things that can help</h3>{activeRequirements.map(req=><div className="path-requirement" key={req.label}><span className={req.met?'req-met':'req-missing'}>{req.met?<Check size={13}/>:<ArrowRight size={12}/>}</span><span>{req.label}</span></div>)}<div className="requirements-help"><Info size={15}/><span>Missing something? It may just be a skill you can learn. A blocker means check with the organisation first.</span></div><button className="text-link" onClick={onCoach}>Get ready for an interview <ArrowRight size={14}/></button>{applied.includes(active.id)&&<div className="applied-note"><CheckCircle2 size={15}/> You’ve saved your interest in this opportunity.</div>}</aside></div>{quizOpen&&<div className="modal-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)setQuizOpen(false)}}><section className="quiz-modal" role="dialog" aria-modal="true"><div className="modal-head"><span className="eyebrow">A QUICK PRACTICE</span><button className="icon-button" onClick={()=>setQuizOpen(false)} aria-label="Close"><X size={20}/></button></div><span className="quiz-icon"><Sparkles size={21}/></span><h2>Practise: {focusSkill}</h2><p>{skillPractice.prompt}</p>{!quizResult?<><div className="quiz-options">{skillPractice.choices.map(choice=><button key={choice.label} className={quizAnswer===choice.label?'chosen':''} onClick={()=>setQuizAnswer(choice.label)}>{choice.label}{quizAnswer===choice.label&&<Check size={15}/>}</button>)}</div><button className="btn btn-dark full-btn" disabled={!quizAnswer} onClick={()=>setQuizResult(true)}>See a helpful tip <ArrowRight size={15}/></button></>:<div className="quiz-feedback"><CheckCircle2 size={20}/><div><b>A thought to take with you</b><p>{skillPractice.choices.find(choice=>choice.label===quizAnswer)?.feedback}</p></div><button className="btn btn-soft" onClick={()=>{setQuizOpen(false);setQuizResult(false);setQuizAnswer('');onComplete('skill-task')}}>Finish this step <Check size={15}/></button></div>}</section></div>}</>
}

function CoachPage({ question,answer,feedback,questions:questionList,profile,history,onQuestion,onAnswer,onPractice,onClear,onDeleteHistory }: {question:string;answer:string;feedback:boolean;questions:typeof questions;profile:Profile;history:Store['answers'];onQuestion:(s:string)=>void;onAnswer:(s:string)=>void;onPractice:()=>void;onClear:()=>void;onDeleteHistory:()=>void}) {
  const activeQuestion=questionList.find(item=>item.title===question)||questionList[0]
  const getSample=()=>activeQuestion.title==='Tell me about yourself'?`I am ${profile.name}, and I live in ${profile.location}. I have reached ${profile.education}. I enjoy ${profile.skills.slice(0,2).join(' and ').toLowerCase()}, and I am ready to learn and contribute in this role.`:`I am interested in this opportunity because it would let me use ${profile.skills[0]?.toLowerCase()||'my skills'} and learn more. I am reliable, willing to learn and ready to give it my best.`
  const answerTip=()=>{
    const text=answer.trim()
    if(text.length<80) return 'Try adding one more detail that answers the question. A small example from home, school or your community is enough.'
    if(!/\b(i|my)\b/i.test(text)) return 'Make it clear what you personally did or would do. Starting one sentence with “I” can help.'
    if(!/\b(for example|when|because|helped|learned|result|then|after)\b/i.test(text)) return 'Add one short example and what happened afterwards. It helps the listener picture your experience.'
    return 'Read your answer aloud once. Keep the part that sounds most like you, and remove anything you would not say naturally.'
  }
  return <><PageHeading eyebrow="PRACTISE IN YOUR OWN TIME" title="Interview practice" description="Try a question, then get a few kind, useful tips. This is practice, not a test." right={<span className="private-pill"><Shield size={15}/> Just for you</span>}/><div className="coach-note"><Sparkles size={17}/><span><b>It’s okay to start small.</b> You can practise as many times as you like. Your answers are private and aren’t shared with employers.</span></div><div className="coach-layout"><section className="coach-main"><div className="coach-card"><div className="coach-topline"><span className="coach-tag">{activeQuestion.group}</span><span className="question-counter">A question to try</span></div><h2>{activeQuestion.title}</h2><div className="guide-box"><span className="guide-icon"><Info size={15}/></span><div><b>A little guide</b><p>{activeQuestion.guide}</p></div></div><label className="answer-label" htmlFor="practice-answer">Your answer</label><textarea id="practice-answer" value={answer} onChange={e=>onAnswer(e.target.value)} maxLength={1200} placeholder="Write it the way you would say it. There’s no perfect answer."/><div className="answer-meta"><span>{answer.length}/1,200</span><button onClick={()=>onAnswer(getSample())}><Sparkles size={14}/> Help me start</button></div>{feedback&&<div className="feedback-panel"><div className="feedback-heading"><span className="feedback-spark"><Sparkles size={15}/></span><div><b>A few things to think about</b><small>Helpful tips, not a score</small></div></div><div className="feedback-points"><div><CheckCircle2 size={16}/><span><b>You gave it a go.</b> Getting started is the hardest part, and you’ve done it.</span></div><div><ArrowUpRight size={16}/><span><b>One next step.</b> {answerTip()}</span></div></div><div className="sample-answer"><span className="eyebrow">A STARTING POINT FROM YOUR PROFILE</span><p>“{getSample()}”</p><small>Only uses details you added to your profile. Change anything that doesn’t sound like you.</small></div></div>}<div className="coach-actions"><button className="btn btn-outline" onClick={onClear}>Clear answer</button><button className="btn btn-dark" disabled={!answer.trim()} onClick={onPractice}>{feedback?'Practise again':'Get helpful tips'} <ArrowRight size={15}/></button></div><div className="ai-limits"><Info size={14}/> Tips use simple practice prompts and stay on this device. They are not a prediction of whether you’ll get the job. Never add private details like your ID number.</div></div></section><aside className="question-side"><div className="eyebrow">PICK A QUESTION</div>{questionList.map((item,index)=><button className={`question-pick ${question===item.title?'active':''}`} key={item.title} onClick={()=>onQuestion(item.title)}><span className="question-number">{String(index+1).padStart(2,'0')}</span><span><small>{item.group}</small><b>{item.title}</b></span>{question===item.title&&<span className="question-active-dot"/>}</button>)}<div className="interview-day"><div className="interview-day-icon"><BriefcaseBusiness size={16}/></div><b>Interview day tip</b><p>Check the venue with the organisation. Tell someone you trust where you’re going, and never pay for an interview.</p></div>{history.length>0&&<button className="history-delete" onClick={onDeleteHistory}>Clear my practice history</button>}</aside></div></>
}

function ProfilePage({profile,onSave}:{profile:Profile;onSave:(p:Profile)=>void}) {
  const [draft,setDraft]=useState(profile)
  const [skillText,setSkillText]=useState('')
  useEffect(()=>setDraft(profile),[profile])
  const addSkill=()=>{const value=skillText.trim();if(value&&!draft.skills.some(skill=>skill.toLowerCase()===value.toLowerCase()))setDraft({...draft,skills:[...draft.skills,value]});setSkillText('')}
  return <><PageHeading eyebrow="ABOUT YOU" title="My profile" description="Share a little about yourself. You can change it whenever you like." right={<span className="private-pill"><Shield size={15}/> Your details stay yours</span>}/><div className="profile-layout"><section className="profile-card"><div className="profile-avatar-wrap"><span className="profile-avatar">{draft.name.trim().split(/\s+/).map(part=>part[0]).join('').slice(0,2).toUpperCase()}</span><div><h2>{draft.name||'Your name'}</h2><p>{draft.location||'Add where you live'}</p></div><span className="profile-level">Your profile</span></div><div className="form-grid"><label>Your name<input value={draft.name} onChange={e=>setDraft({...draft,name:e.target.value})} placeholder="What should we call you?"/></label><label>Where do you live?<input value={draft.location} onChange={e=>setDraft({...draft,location:e.target.value})} placeholder="Town or area"/></label><label>Last school level completed<select value={draft.education} onChange={e=>setDraft({...draft,education:e.target.value})}><option value="">Choose a school level (optional)</option><option>Some primary school</option><option>Grade 7</option><option>Grade 8</option><option>Grade 9</option><option>Grade 10</option><option>Grade 11</option><option>Grade 12</option><option>Other</option></select><small>You don’t need matric to use ThusaPath.</small></label><label>Tell us a little about yourself<textarea value={draft.about} onChange={e=>setDraft({...draft,about:e.target.value})} placeholder="What do you enjoy? What are you proud of?" maxLength={500}/><small>{draft.about.length}/500</small></label><div className="skill-editor"><b>Things you know or enjoy</b><p>Skills can come from school, home, a sport or helping in your community.</p><div className="skill-chips">{draft.skills.map(skill=><button key={skill} onClick={()=>setDraft({...draft,skills:draft.skills.filter(item=>item!==skill)})}>{skill}<X size={12}/></button>)}</div><div className="skill-add"><input value={skillText} onChange={e=>setSkillText(e.target.value)} onKeyDown={e=>{if(e.key==='Enter'){e.preventDefault();addSkill()}}} placeholder="Add something you can do"/><button className="btn btn-soft" onClick={addSkill}>Add</button></div></div></div><div className="profile-save-row"><span><Info size={14}/> Don’t add your ID number or bank details.</span><button className="btn btn-dark" onClick={()=>onSave(draft)}>Save my profile <Check size={15}/></button></div></section><aside className="profile-privacy"><span className="privacy-illustration"><ShieldCheck size={25}/></span><h3>Your privacy matters</h3><p>Your profile stays on this device. ThusaPath does not send it to employers.</p><div><CheckCircle2 size={15}/> We never ask for your ID document</div><div><CheckCircle2 size={15}/> Your interview practice is private</div><div><CheckCircle2 size={15}/> Change or remove your details anytime</div></aside></div></>
}

function GoalsPage({goals,opportunities,onSave,onToast}:{goals:Goal[];opportunities:Opportunity[];onSave:(goals:Goal[])=>void;onToast:(message:string)=>void}) {
  const [adding,setAdding]=useState(false)
  const [title,setTitle]=useState('')
  const [opportunityId,setOpportunityId]=useState('')
  const [filter,setFilter]=useState<'all'|'open'|'done'>('all')
  const visible=goals.filter(goal=>filter==='all'||(filter==='done'?goal.done:!goal.done))
  const save=()=>{const clean=title.trim();if(!clean)return;onSave([{id:`goal-${Date.now()}`,title:clean,opportunityId:opportunityId||undefined,done:false,createdAt:new Date().toISOString()},...goals]);setTitle('');setOpportunityId('');setAdding(false);onToast('Your goal is saved.')}
  const toggle=(id:string)=>onSave(goals.map(goal=>goal.id===id?{...goal,done:!goal.done}:goal))
  const remove=(id:string)=>{onSave(goals.filter(goal=>goal.id!==id));onToast('Goal removed.')}
  return <><PageHeading eyebrow="YOUR GOALS, YOUR PACE" title="My goals" description="Choose something you’d like to work towards. Small goals count." right={<div className="goal-summary"><span>{goals.filter(goal=>goal.done).length}<small> / {goals.length}</small></span><b>goals done</b></div>}/><div className="goals-intro"><span className="goals-intro-icon"><Heart size={18}/></span><div><b>This is your plan. You choose what matters.</b><p>Make a goal as small and practical as you like. You can change it anytime.</p></div><button className="btn btn-dark" onClick={()=>setAdding(!adding)}>{adding?<X size={15}/>:<Plus size={15}/>} {adding?'Close':'Add a goal'}</button></div>{adding&&<section className="goal-form"><div className="goal-form-title"><span className="goal-form-number">1</span><div><b>What would you like to do?</b><small>For example, “Practise an interview answer”.</small></div></div><label className="goal-input-label">My goal<input autoFocus value={title} maxLength={90} onChange={e=>setTitle(e.target.value)} onKeyDown={e=>{if(e.key==='Enter'&&title.trim())save()}} placeholder="Write a goal in your own words"/></label><label className="goal-input-label">Link it to an opportunity <small>Optional</small><select value={opportunityId} onChange={e=>setOpportunityId(e.target.value)}><option value="">No opportunity selected</option>{opportunities.map(item=><option key={item.id} value={item.id}>{item.title} · {item.organisation}</option>)}</select></label><div className="goal-form-actions"><button className="btn btn-outline" onClick={()=>{setAdding(false);setTitle('');setOpportunityId('')}}>Cancel</button><button className="btn btn-dark" disabled={!title.trim()} onClick={save}>Save my goal <ArrowRight size={14}/></button></div></section>}<div className="goal-list-heading"><div><div className="eyebrow">YOUR LIST</div><h2>One step at a time</h2></div><div className="goal-filters">{([['all','All'],['open','To do'],['done','Done']] as const).map(([id,label])=><button key={id} className={filter===id?'active':''} onClick={()=>setFilter(id)}>{label}</button>)}</div></div>{visible.length?<div className="goal-list">{visible.map(goal=>{const linked=opportunities.find(item=>item.id===goal.opportunityId);return <article className={`goal-card ${goal.done?'goal-card-done':''}`} key={goal.id}><button className={`goal-check ${goal.done?'checked':''}`} onClick={()=>toggle(goal.id)} aria-label={goal.done?'Mark goal as not done':'Mark goal as done'}>{goal.done&&<Check size={15}/>}</button><div className="goal-card-copy"><h3>{goal.title}</h3><div className="goal-meta">{linked&&<span><BriefcaseBusiness size={12}/>{linked.title}</span>}<span>{goal.done?'Completed':'Added'} {new Date(goal.createdAt).toLocaleDateString('en-ZA',{day:'numeric',month:'short'})}</span></div></div><span className={`goal-status ${goal.done?'complete':''}`}>{goal.done?'Done':'In progress'}</span><button className="goal-remove" onClick={()=>remove(goal.id)} aria-label="Remove goal"><Trash2 size={15}/></button></article>})}</div>:<div className="goals-empty"><span className="goals-empty-icon"><CheckCircle2 size={21}/></span><h3>{filter==='done'?'No finished goals yet':'Start with one small goal'}</h3><p>{filter==='done'?'When you finish a goal, you’ll find it here.':'A goal could be practising an answer, adding a skill to your profile or looking at one opportunity.'}</p>{filter!=='done'&&<button className="btn btn-soft" onClick={()=>setAdding(true)}><Plus size={14}/> Add my first goal</button>}</div>}</>
}

function CVPage({profile,cvs,onSave,onToast,onConfirmAction}:{profile:Profile;cvs:CV[];onSave:(cvs:CV[])=>void;onToast:(message:string)=>void;onConfirmAction:(config:ConfirmationConfig)=>void}) {
  const [activeId,setActiveId]=useState(cvs[0]?.id||'cv-first')
  const cv=cvs.find(item=>item.id===activeId)||cvs[0]
  const update=(changes:Partial<CV>)=>onSave(cvs.map(item=>item.id===cv.id?{...item,...changes}:item))
  const create=()=>{const next:CV={id:`cv-${Date.now()}`,title:`My CV ${cvs.length+1}`,email:'',phone:'',summary:'',experience:'',education:'',template:'clean'};onSave([...cvs,next]);setActiveId(next.id);onToast('A new CV is ready to edit.')}
  const duplicate=()=>{const next={...cv,id:`cv-${Date.now()}`,title:`${cv.title} (copy)`};onSave([...cvs,next]);setActiveId(next.id);onToast('A copy of your CV has been made.')}
  const remove=()=>onConfirmAction({title:cvs.length===1?'Clear this CV?':'Delete this CV?',message:cvs.length===1?'This will clear the details in your only CV. Your profile details will stay saved.':'This will permanently remove this CV from this device.',confirmLabel:cvs.length===1?'Clear CV':'Delete CV',onConfirm:()=>{if(cvs.length===1){onSave([{...cv,title:'My CV',email:'',phone:'',summary:'',experience:'',education:'',template:'clean'}]);onToast('Your CV has been cleared.')}else{const next=cvs.filter(item=>item.id!==cv.id);onSave(next);setActiveId(next[0].id);onToast('Your CV has been removed.')}}})
  return <div className="cv-page-container"><PageHeading eyebrow="YOUR DETAILS, YOUR STORY" title="CV Studio" description="Put your skills and experience on one page. No work history? That’s okay." right={<span className="private-pill"><Shield size={15}/> Saved on this device</span>}/><div className="cv-toolbar"><label className="cv-picker-label">Choose a CV<select value={cv.id} onChange={e=>setActiveId(e.target.value)}>{cvs.map(item=><option key={item.id} value={item.id}>{item.title}</option>)}</select></label><div className="cv-toolbar-actions"><button className="btn btn-outline" onClick={create}><Plus size={14}/> New CV</button><button className="btn btn-outline" onClick={duplicate}><Copy size={14}/> Make a copy</button><button className="btn btn-outline danger-outline" onClick={remove}><Trash2 size={14}/> Clear or delete</button><button className="btn btn-dark" onClick={()=>{window.print();onToast('Choose “Save as PDF” in the print window to download your CV.')}}><Download size={15}/> Print or save as PDF</button></div></div><div className="cv-layout"><section className="cv-builder-controls"><div className="cv-section-heading"><span className="cv-step">1</span><div><b>Choose a look</b><small>Pick the style that feels like you.</small></div></div><div className="template-options"><button className={`template-option ${cv.template==='clean'?'selected':''}`} onClick={()=>update({template:'clean'})}><span className="template-preview clean-preview"><i/><i/><i/><i/></span><span><b>Simple</b><small>Clear and easy to read</small></span>{cv.template==='clean'&&<CheckCircle2 size={16}/>}</button><button className={`template-option ${cv.template==='warm'?'selected':''}`} onClick={()=>update({template:'warm'})}><span className="template-preview warm-preview"><i/><i/><i/><i/></span><span><b>Warm</b><small>A little more colour</small></span>{cv.template==='warm'&&<CheckCircle2 size={16}/>}</button></div><div className="cv-section-heading cv-form-title"><span className="cv-step">2</span><div><b>Add your details</b><small>Your name and skills come from your profile.</small></div></div><label className="cv-field">CV name<input value={cv.title} onChange={e=>update({title:e.target.value})} placeholder="For example: My shop CV"/></label><div className="cv-two-fields"><label className="cv-field">Email (optional)<input type="email" value={cv.email} onChange={e=>update({email:e.target.value})} placeholder="you@example.com"/></label><label className="cv-field">Phone (optional)<input type="tel" value={cv.phone} onChange={e=>update({phone:e.target.value})} placeholder="Your phone number"/></label></div><label className="cv-field">A short introduction<textarea value={cv.summary||profile.about} onChange={e=>update({summary:e.target.value})} maxLength={500} placeholder="What are you like? What would you bring?"/><small>Say what you’re good at and what you’re ready to learn.</small></label><label className="cv-field">Things you’ve done<textarea value={cv.experience} onChange={e=>update({experience:e.target.value})} maxLength={1000} placeholder="Helping at home, school projects, sport, community work or a job all count."/><small>You don’t need a formal job to have useful experience.</small></label><label className="cv-field">School level or learning<textarea value={cv.education||profile.education} onChange={e=>update({education:e.target.value})} maxLength={300} placeholder="For example: Grade 10"/></label><div className="cv-privacy-note"><ShieldCheck size={15}/><span>Only include contact details you’re comfortable sharing. Your CV is saved on this device until you choose to send it.</span></div><button className="btn btn-soft cv-save-button" onClick={()=>{onSave(cvs);onToast('Your CV is saved on this device.')}}><Check size={15}/> Save my changes</button></section><section className="cv-preview-wrap"><div className="cv-preview-label"><span><FileText size={14}/> LIVE PREVIEW</span><small>What your CV will look like</small></div><CVPreview profile={profile} cv={cv}/></section></div></div>
}

function CVPreview({profile,cv}:{profile:Profile;cv:CV}) { return <article id="cv-document" className={`cv-document ${cv.template==='warm'?'cv-warm':''}`}><header className="cv-doc-header"><div className="cv-doc-monogram">{profile.name.trim().split(/\s+/).map(part=>part[0]).join('').slice(0,2).toUpperCase()||'Y'}</div><div><h2>{profile.name||'Your name'}</h2><p>{[profile.location,cv.phone,cv.email].filter(Boolean).join('  ·  ')}</p></div></header><section className="cv-doc-section"><h3>ABOUT ME</h3><p>{cv.summary||profile.about||'Write a few lines about yourself, what you enjoy and what you are ready to learn.'}</p></section><section className="cv-doc-section"><h3>MY SKILLS</h3>{profile.skills.length?<div className="cv-doc-skills">{profile.skills.map(skill=><span key={skill}>{skill}</span>)}</div>:<p>Add some skills from your profile.</p>}</section><section className="cv-doc-section"><h3>EXPERIENCE</h3><p>{cv.experience||'You can include helping at home, school projects, sport or community activities. Add your experience in CV Studio.'}</p></section><section className="cv-doc-section"><h3>EDUCATION</h3><p>{cv.education||profile.education||'Add the last school level you completed.'}</p><span className="cv-doc-location">{profile.location}</span></section><footer className="cv-doc-footer">References available on request</footer></article> }

function AuthPage({onAdminSignIn,onUserSignIn}:{onAdminSignIn:(session:AdminSession)=>void;onUserSignIn:(session:AdminSession)=>void}) {
  const [mode,setMode]=useState<'signin'|'register'>('signin')
  const [firstName,setFirstName]=useState('')
  const [lastName,setLastName]=useState('')
  const [email,setEmail]=useState('')
  const [password,setPassword]=useState('')
  const [confirmPassword,setConfirmPassword]=useState('')
  const [error,setError]=useState('')
  const [notice,setNotice]=useState('')
  const [busy,setBusy]=useState(false)
  const submit=async(event:FormEvent<HTMLFormElement>)=>{
    event.preventDefault()
    setError('')
    setNotice('')
    setBusy(true)
    try {
      const normalized=email.trim().toLowerCase()
      if(mode==='register') {
        if(!firstName.trim()||!lastName.trim()) throw new Error('Enter your first name and surname.')
        if(password.length<8) throw new Error('Choose a password with at least 8 characters.')
        if(password!==confirmPassword) throw new Error('Those passwords do not match.')
        const result=await signUpJobSeeker(normalized,password,firstName,lastName)
        if(result.session){onUserSignIn(result.session);return}
        setMode('signin')
        setPassword('')
        setConfirmPassword('')
        setNotice('Your account is ready. Check your email for a confirmation link, then sign in.')
        return
      }
      if(normalized.endsWith('@thusapath.com')) {
        onAdminSignIn(await signInAdmin(normalized,password))
        return
      }
      onUserSignIn(await signInJobSeeker(normalized,password))
    } catch(cause) {
      setError(cause instanceof Error?cause.message:'We could not complete that. Please try again.')
    } finally {
      setBusy(false)
    }
  }
  return <div className="auth-screen"><header className="auth-screen-header"><Brand onClick={()=>{}}/><span>A simple place to find your next step</span></header><div className="auth-content"><PageHeading eyebrow="YOUR THUSAPATH ACCOUNT" title={mode==='signin'?'Welcome back':'Create your account'} description="Use the same page to sign in or register."/><section className="admin-login-card auth-card"><div className="admin-login-art"><span><LockKeyhole size={23}/></span><h2>{mode==='signin'?'Your next step starts here':'A place for your progress'}</h2><p>{mode==='signin'?'Sign in to your ThusaPath account to continue.':'Create your account with your name and email. You can add more details later.'}</p><div><ShieldCheck size={15}/> Your details are kept private</div></div><form className="admin-login-form" onSubmit={submit}><div className="auth-tabs" role="tablist" aria-label="Account options"><button type="button" role="tab" aria-selected={mode==='signin'} className={mode==='signin'?'active':''} onClick={()=>{setMode('signin');setError('');setNotice('')}}>Sign in</button><button type="button" role="tab" aria-selected={mode==='register'} className={mode==='register'?'active':''} onClick={()=>{setMode('register');setError('');setNotice('')}}>Register</button></div>{mode==='register'&&<div className="auth-name-fields"><label>First name<input required autoComplete="given-name" value={firstName} onChange={event=>setFirstName(event.target.value)} placeholder="Your first name"/></label><label>Surname<input required autoComplete="family-name" value={lastName} onChange={event=>setLastName(event.target.value)} placeholder="Your surname"/></label></div>}<label>Email address<input required type="email" autoComplete="username" value={email} onChange={event=>setEmail(event.target.value)} placeholder="you@example.com"/></label><label>Password<input required minLength={8} type="password" autoComplete={mode==='register'?'new-password':'current-password'} value={password} onChange={event=>setPassword(event.target.value)} placeholder={mode==='register'?'At least 8 characters':'Your password'}/></label>{mode==='register'&&<label>Confirm password<input required minLength={8} type="password" autoComplete="new-password" value={confirmPassword} onChange={event=>setConfirmPassword(event.target.value)} placeholder="Type your password again"/></label>}{notice&&<div className="auth-notice" role="status">{notice}</div>}{error&&<div className="admin-error" role="alert">{error}</div>}<button className="btn btn-dark" type="submit" disabled={busy}>{busy?(mode==='register'?'Creating account…':'Signing in…'):mode==='register'?'Create account':'Sign in'} <ArrowRight size={15}/></button></form></section></div><div className="auth-screen-help">Need help? Send an email to <b>admin@thusaPath.com</b></div></div>
}
function TrustReviewDesk({session}:{session:AdminSession}) {
  const [organisations,setOrganisations]=useState<OrganisationReview[]>([])
  const [reports,setReports]=useState<OpportunityReport[]>([])
  const [loading,setLoading]=useState(false)
  const [error,setError]=useState('')
  const [notice,setNotice]=useState('')
  const [name,setName]=useState('')
  const [registrationNumber,setRegistrationNumber]=useState('')
  const [drafts,setDrafts]=useState<Record<string,{method:string;notes:string;verifiedUntil:string}>>({})
  const reload=async()=>{
    setLoading(true);setError('')
    try { const data=await loadTrustQueue(session);setOrganisations(data.organisations);setReports(data.reports) }
    catch { setError('The trust review tables are not ready yet. Apply the ThusaPath trust review migration in Supabase, then refresh this page.') }
    finally { setLoading(false) }
  }
  useEffect(()=>{void reload()},[session.userId])
  const draftFor=(id:string)=>drafts[id]||{method:'Official organisation website',notes:'',verifiedUntil:new Date(Date.now()+365*24*60*60*1000).toISOString().slice(0,10)}
  const changeDraft=(id:string,change:Partial<{method:string;notes:string;verifiedUntil:string}>)=>setDrafts(current=>({ ...current,[id]:{...draftFor(id),...change} }))
  const addOrganisation=async(event:FormEvent<HTMLFormElement>)=>{
    event.preventDefault();setError('');setNotice('')
    try { await addOrganisationForReview(session,name,registrationNumber);setName('');setRegistrationNumber('');setNotice('The employer has been added to the review list.');await reload() }
    catch(cause) { setError(cause instanceof Error?cause.message:'Could not add this employer.') }
  }
  const decideOrganisation=async(org:OrganisationReview,status:'verified'|'rejected')=>{
    const draft=draftFor(org.id);setError('');setNotice('')
    try { await reviewOrganisation(session,org.id,status,draft.method,draft.notes,draft.verifiedUntil);setNotice(status==='verified'?'Employer details checked and recorded.':'Review decision recorded.');await reload() }
    catch(cause) { setError(cause instanceof Error?cause.message:'Could not save this review.') }
  }
  const setReportState=async(report:OpportunityReport,status:OpportunityReport['status'])=>{
    setError('');setNotice('')
    try { await updateReportStatus(session,report.id,status);setNotice('Report status updated.');await reload() }
    catch(cause) { setError(cause instanceof Error?cause.message:'Could not update this report.') }
  }
  return <section className="trust-desk">
    <div className="trust-desk-heading"><div><span className="eyebrow">TRUST AND SAFETY</span><h2>Employer checks and user reports</h2><p>Record what was checked, when it was checked, and what happened to safety reports.</p></div><button className="btn btn-outline" onClick={()=>void reload()} disabled={loading}>{loading?'Refreshing…':'Refresh review list'}</button></div>
    {error&&<div className="admin-error" role="alert">{error}</div>}{notice&&<div className="auth-notice" role="status">{notice}</div>}
    <div className="trust-review-layout"><section className="trust-panel"><div className="trust-panel-heading"><div><h3>Employer verification</h3><p>Only verify after checking an official record and a separate contact channel.</p></div><span>{organisations.filter(org=>org.status==='pending').length} pending</span></div>
      <form className="trust-add-form" onSubmit={addOrganisation}><label>Employer or organisation name<input required maxLength={160} value={name} onChange={event=>setName(event.target.value)} placeholder="Name as it appears on its official record"/></label><label>Registration number<input required maxLength={100} value={registrationNumber} onChange={event=>setRegistrationNumber(event.target.value)} placeholder="Official registration number"/></label><button className="btn btn-dark" type="submit" disabled={loading}>Add for review <Plus size={14}/></button></form>
      {organisations.length?<div className="trust-record-list">{organisations.map(org=>{const draft=draftFor(org.id);return <article className="trust-record" key={org.id}><div className="trust-record-top"><div><b>{org.name}</b><small>Registration number: {org.registration_number}</small></div><span className={`trust-status ${org.status}`}>{org.status==='verified'?'Verified':org.status==='rejected'?'Not approved':'Needs review'}</span></div>{org.status==='verified'&&<div className="trust-record-meta">Checked by staff on {org.verified_at?new Date(org.verified_at).toLocaleDateString('en-ZA'):'date not recorded'} · {org.verification_method||'method not recorded'} · valid to {org.verified_until||'not recorded'}</div>}{org.verification_notes&&<p className="trust-record-notes">{org.verification_notes}</p>}<div className="trust-decision-form"><label>How did you check?<select value={draft.method} onChange={event=>changeDraft(org.id,{method:event.target.value})}><option>Official organisation website</option><option>CIPC or another official register</option><option>Public sector source</option><option>Confirmed with an existing partner</option><option>Other official source</option></select></label><label>What did you check? Leave out private document numbers.<textarea value={draft.notes} maxLength={700} onChange={event=>changeDraft(org.id,{notes:event.target.value})} placeholder="For example: matched the organisation name and registration number against its official record; confirmed contact details through its official website."/></label><label>Check valid until<input type="date" value={draft.verifiedUntil} onChange={event=>changeDraft(org.id,{verifiedUntil:event.target.value})}/></label><div className="trust-decision-actions"><button className="btn btn-outline" onClick={()=>void decideOrganisation(org,'rejected')} disabled={loading}>Do not approve</button><button className="btn btn-dark" onClick={()=>void decideOrganisation(org,'verified')} disabled={loading}>{org.status==='verified'?'Renew verified check':'Record verified check'} <ShieldCheck size={14}/></button></div></div></article>})}</div>:!loading&&!error&&<div className="admin-empty">No employers are waiting for review. Add one above when you have an official record to check.</div>}
    </section><section className="trust-panel"><div className="trust-panel-heading"><div><h3>Safety reports</h3><p>Reports from job seekers are stored for staff review.</p></div><span>{reports.filter(report=>report.status==='open'||report.status==='in_review').length} open</span></div>
      {reports.length?<div className="trust-record-list">{reports.map(report=><article className="trust-record" key={report.id}><div className="trust-record-top"><div><b>{report.listing_title}</b><small>{report.organisation_name} · {new Date(report.created_at).toLocaleString('en-ZA')}</small></div><span className={`trust-status ${report.status}`}>{report.status.replace('_',' ')}</span></div><p className="trust-report-reason">{report.reason}</p>{report.note&&<p className="trust-record-notes">{report.note}</p>}<div className="trust-report-meta">Source: {report.source_name||'not recorded'} · Application site: {report.application_host||'not recorded'}</div><div className="trust-decision-actions"><button className="btn btn-outline" onClick={()=>void setReportState(report,'in_review')} disabled={loading||report.status==='in_review'}>Mark in review</button><button className="btn btn-dark" onClick={()=>void setReportState(report,'resolved')} disabled={loading||report.status==='resolved'}>Resolve report <Check size={14}/></button><button className="trust-dismiss" onClick={()=>void setReportState(report,'dismissed')} disabled={loading||report.status==='dismissed'}>Dismiss</button></div></article>)}</div>:!loading&&!error&&<div className="admin-empty">No reports have been sent yet. User reports will appear here for follow-up.</div>}
    </section></div>
  </section>
}

function AdminDashboard({session,listings,status,lastRefresh,onRefresh,onLogout}:{session:AdminSession;listings:Opportunity[];status:OpportunityLoadStatus;lastRefresh:Date|null;onRefresh:()=>void;onLogout:()=>void}) {
  const sourced=listings.filter(item=>item.sourceName)
  const firstParty=listings.filter(item=>!item.sourceName||item.sourceName==='ThusaPath')
  const externalListings=listings.filter(item=>item.sourceName&&item.sourceName!=='ThusaPath')
  const feedEnabled=import.meta.env.VITE_ADZUNA_ENABLED==='true'||import.meta.env.VITE_EXTERNAL_LISTINGS_ENABLED==='true'
  return <><PageHeading eyebrow="STAFF WORKSPACE" title="Listing sources" description="Check live listing feeds and refresh what job seekers can see." right={<button className="btn btn-outline admin-logout" onClick={onLogout}><LogOut size={15}/> Sign out</button>}/><div className="admin-welcome"><span className="admin-avatar"><ShieldCheck size={19}/></span><div><b>Signed in as {session.email}</b><small>Only approved ThusaPath staff accounts can open this area.</small></div></div><TrustReviewDesk session={session}/><section className="admin-source-card"><div className="admin-source-head"><div><span className="eyebrow">CONNECTED LISTINGS</span><h2>Opportunity feed</h2><p>The connection runs securely on the server. Private API keys are never entered or shown on this page.</p></div><span className={`admin-status-pill ${status==='live'?'online':''}`}><i/>{status==='loading'?'Checking':status==='live'?'Listings available':status==='unconfigured'?'Needs setup':status==='empty'?'No current opportunities':'Connection issue'}</span></div><div className="admin-metrics"><div><b>{listings.length}</b><span>Listings available</span></div><div><b>{externalListings.length}</b><span>From connected listing feeds</span></div><div><b>{firstParty.length}</b><span>ThusaPath checked listings</span></div></div><div className="admin-feed-row"><div><b>External listing connection</b><p>{feedEnabled?'Connection is enabled. Listings are fetched by the secure server function.':'Not enabled yet. Add provider credentials to the server before switching it on.'}</p></div><span className={`admin-feed-state ${feedEnabled?'enabled':''}`}>{feedEnabled?'Enabled':'Not configured'}</span></div><div className="admin-refresh-row"><span>{lastRefresh?`Last checked ${lastRefresh.toLocaleTimeString('en-ZA',{hour:'2-digit',minute:'2-digit'})}`:'No refresh yet in this session'}</span><button className="btn btn-dark" onClick={onRefresh} disabled={status==='loading'}>{status==='loading'?'Checking…':'Refresh listings'} <ArrowRight size={15}/></button></div></section><section className="admin-listings"><div className="admin-listings-heading"><div><span className="eyebrow">CURRENT FEED</span><h2>Listings being shown</h2></div><span>{sourced.length} sourced listing{sourced.length===1?'':'s'}</span></div>{listings.length?<div className="admin-listing-list">{listings.map(item=><article key={item.id}><div><b>{item.title}</b><p>{item.organisation} · {item.place}</p></div><span className={`admin-listing-badge ${item.verifiedByUs===false?'source':''}`}><ShieldCheck size={13}/>{item.verifiedByUs===true?'ThusaPath checked':item.verificationStatus==='unavailable'?'Check details unavailable':'Source listing · not checked'}</span></article>)}</div>:<div className="admin-empty">No listings are available right now. Check the connection settings and try refreshing.</div>}</section></>
}

export default App
